// Configurações do projeto — substituir pelos valores reais
const SUPABASE_URL = 'https://syecwttpsvrmhdvinjmt.supabase.co';
const SUPABASE_SERVICE_KEY = 'SUPABASE_SERVICE_ROLE_KEY_AQUI';
const STORAGE_BUCKET = 'instagram-covers';

return [{
  json: {
    SUPABASE_URL,
    SUPABASE_SERVICE_KEY,
    STORAGE_BUCKET
  }
}];

const data = $input.item.json;
if (!Array.isArray(data) || data.length === 0) return [];
return data.map(post => ({ json: post }));

const post = $input.item.json;

// Derivar URL de capa por tipo de mídia (sem nova chamada à API)
let coverSourceUrl = null;

if (post.media_type === 'IMAGE') {
  coverSourceUrl = post.media_url || null;
} else if (post.media_type === 'VIDEO') {
  coverSourceUrl = post.thumbnail_url || post.media_url || null;
} else if (post.media_type === 'CAROUSEL_ALBUM') {
  // Para carrosséis, media_url pode conter a capa do álbum
  // Se não, o post será pulado e tratado por uma segunda passagem com chamada à API
  coverSourceUrl = post.media_url || post.thumbnail_url || null;
}

return {
  json: {
    ...post,
    cover_source_url: coverSourceUrl,
    has_source: Boolean(coverSourceUrl)
  }
};

// Verificar se o download teve sucesso
const item = $input.item;
const post = $('Derivar URL de Capa').item.json;

// Se houve erro no download, retornar flag de falha
if (item.error || !item.binary?.data) {
  return {
    json: {
      ...post,
      download_ok: false,
      download_error: item.error?.message || 'Sem dados binários'
    }
  };
}

return {
  json: {
    ...post,
    download_ok: true,
    file_size: item.binary.data.fileSize || 0
  },
  binary: item.binary
};

const uploadResult = $input.item.json;
const post = $('Verificar Download').item.json;

// Verificar se o upload teve sucesso (Supabase Storage retorna { Key: '...' })
const uploadOk = !$input.item.error && (uploadResult.Key || uploadResult.Id);

const SUPABASE_URL = 'https://syecwttpsvrmhdvinjmt.supabase.co';
const coverUrl = uploadOk
  ? `${SUPABASE_URL}/storage/v1/object/public/instagram-covers/${post.username}/${post.post_id}.jpg`
  : null;

return {
  json: {
    post_id: post.post_id,
    cover_url: coverUrl,
    upload_ok: uploadOk,
    upload_error: $input.item.error?.message || null
  }
};

// Log de sucesso
const d = $input.item.json;
console.log(`[OK] ${d.post_id} → cover_url atualizada`);
return { json: { status: 'ok', post_id: d.post_id } };

const d = $input.item.json;
console.warn(`[ERRO UPLOAD] post_id=${d.post_id} error=${d.upload_error}`);
return { json: { status: 'upload_failed', post_id: d.post_id, error: d.upload_error } };

const d = $input.item.json;
console.warn(`[ERRO DOWNLOAD] post_id=${d.post_id} url=${d.cover_source_url} error=${d.download_error}`);
return { json: { status: 'download_failed', post_id: d.post_id, url: d.cover_source_url, error: d.download_error } };

const d = $input.item.json;
console.info(`[SEM URL] post_id=${d.post_id} media_type=${d.media_type} — sem cover_source_url (carrossel sem media_url ou post removido)`);
return { json: { status: 'no_url', post_id: d.post_id, media_type: d.media_type } };
